y starts fresh.","days":[{"day_index":1,"weekday":"Monday","scheduled_on":"2026-12-28","title":"Upper Closeout","focus":"Quality + measurements","exercises":[{"name":"Incline Dumbbell Bench Press","sets":3,"reps":"8"},{"name":"Chest-Supported Dumbbell Row","sets":3,"reps":"8–10"},{"name":"Neutral-Grip Cable Pulldown","sets":2,"reps":"10"},{"name":"Cable Lateral Raise","sets":2,"reps":"12–15"},{"name":"Hammer Curl","sets":2,"reps":"10"},{"name":"Overhead Cable Triceps Extension","sets":2,"reps":"10–12"}]},{"day_index":2,"weekday":"Wednesday","scheduled_on":"2026-12-30","title":"Lower Closeout","focus":"Quiet legs","exercises":[{"name":"Bulgarian Split Squat","sets":2,"reps":"6 / leg"},{"name":"Dumbbell Romanian Deadlift","sets":2,"reps":"6"},{"name":"Bent-Knee Calf Raise","sets":2,"reps":"12"},{"name":"Cable Hip Adduction","sets":2,"reps":"12 / side"},{"name":"Pallof Press","sets":2,"reps":"8 / side"}]}]}]$json$::jsonb;
begin
  select a.id into v_athlete
  from public.athletes a
  where a.slug = 'adrian' and a.active;

  if v_athlete is null then
    raise exception 'Adrian must already exist; never create a duplicate athlete from this migration';
  end if;

  select m.user_id into v_coach
  from public.athlete_memberships m
  where m.athlete_id = v_athlete
    and m.role = 'coach'
    and m.status = 'active'
  order by m.created_at
  limit 1;

  if v_coach is null then
    raise exception 'Adrian needs an active coach membership before the season can be authored';
  end if;

  if exists (
    select 1 from public.training_blocks b
    where b.athlete_id = v_athlete and b.status = 'active'
  ) then
    raise exception 'Adrian already has an active canonical block; reconcile it instead of creating a second source of truth';
  end if;

  update public.athletes
  set program_name = 'The Developed Runner · 2026',
      goal_label = 'Add useful mass and strength without degrading running',
      updated_at = now()
  where id = v_athlete;

  insert into public.training_blocks (
    athlete_id, source, name, block_number, target_event, goal_label,
    current_week, total_weeks, starts_on, ends_on, status, authored_by,
    race_on, goal_statement, week_starts_on, purpose, race_name, race_place
  ) values (
    v_athlete, 'coach_authored', 'The Developed Runner · 2026', 1, null,
    'Add useful mass and strength without degrading running',
    1, 16, date '2026-09-14', date '2026-12-31', 'active', v_coach,
    null,
    'Build a visibly stronger, more substantial runner while preserving running quality. Strength yields to the running plan. Race anchors reported by the athlete: Rockin Rib Run 10K on November 15, Rotary Half Marathon in Weston on December 6, then Mesa Marathon in the next cycle.',
    1, 'development', null, null
  ) returning id into v_block;

  for v_week_json in select value from jsonb_array_elements(v_spec)
  loop
    v_week_state := case when (v_week_json->>'week')::int = 1 then 'in_progress' else 'planned' end;

    insert into public.training_weeks (
      athlete_id, block_id, week_number, starts_on, ends_on, intent,
      matters_because, state, authored_by
    ) values (
      v_athlete,
      v_block,
      (v_week_json->>'week')::smallint,
      (v_week_json->>'start_date')::date,
      (v_week_json->>'end_date')::date,
      v_week_json->>'intent',
      coalesce(nullif(v_week_json->>'progression_note',''), 'Protect the running week and keep the strength dose repeatable.'),
      v_week_state,
      v_coach
    ) returning id into v_week;

    for v_day_json in select value from jsonb_array_elements(v_week_json->'days')
    loop
      insert into public.planned_sessions (
        athlete_id, week_id, scheduled_on, day_label, position, state,
        created_by, is_key, role
      ) values (
        v_athlete,
        v_week,
        (v_day_json->>'scheduled_on')::date,
        v_day_json->>'weekday',
        (v_day_json->>'day_index')::smallint,
        'published',
        v_coach,
        false,
        'support'
      ) returning id into v_session;

      select string_agg(
        format('%s — %s × %s', e->>'name', e->>'sets', e->>'reps'),
        E'\n'
        order by ord
      )
      into v_details
      from jsonb_array_elements(v_day_json->'exercises') with ordinality as x(e,ord);

      insert into public.planned_session_versions (
        athlete_id, planned_session_id, version_number, title,
        prescribed_distance, distance_unit, prescribed_duration_minutes,
        intent, details, change_reason, authored_by, rpe_low, rpe_high,
        pace_low, pace_high, shape, coach_note
      ) values (
        v_athlete,
        v_session,
        1,
        v_day_json->>'title',
        null, null, null,
        v_day_json->>'focus',
        v_details,
        null,
        v_coach,
        null, null, null, null,
        'strength',
        nullif(v_week_json->>'progression_note','')
      );
    end loop;
  end loop;
end
$migration$;
